.sys-layout {
  display: flex;
  gap: 40px;
  margin-top: 40px;
}

.sys-sidebar {
  width: 280px;
  flex-shrink: 0;
}

.sidebar-sticky {
  position: sticky;
  top: 100px;
  background-color: #fff;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  padding: 20px;
  box-shadow: var(--shadow-sm);
}

.sidebar-title {
  font-family: var(--font-headers);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--blue-primary);
  margin-bottom: 20px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--gold-primary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.sidebar-menu {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sidebar-menu-btn {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border: none;
  background: none;
  text-align: left;
  font-family: var(--font-body);
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition-smooth);
  width: 100%;
}

.sidebar-menu-btn:hover {
  background-color: var(--blue-light);
  color: var(--blue-primary);
}

.sidebar-menu-btn.active {
  background-color: var(--blue-primary);
  color: #fff;
}

.sidebar-menu-btn.active i {
  color: var(--gold-primary);
}

.sys-content {
  flex-grow: 1;
  min-width: 0;
}

.content-card {
  background-color: #fff;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  padding: 35px;
  box-shadow: var(--shadow-sm);
  margin-bottom: 30px;
  animation: fadeIn 0.4s ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.card-title {
  font-family: var(--font-headers);
  font-size: 1.6rem;
  color: var(--blue-primary);
  font-weight: 700;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.card-title i {
  color: var(--gold-primary);
}

.info-highlight-box {
  background-color: var(--blue-light);
  border-left: 4px solid var(--blue-primary);
  padding: 25px;
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  margin-bottom: 25px;
}

.info-highlight-box p {
  color: var(--blue-dark);
  font-weight: 500;
  line-height: 1.6;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  margin-top: 25px;
}

.feature-box {
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 25px;
  background-color: #faf9fc;
  transition: var(--transition-smooth);
}

.feature-box:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-sm);
  border-color: var(--blue-primary);
}

.feature-box h3 {
  font-family: var(--font-headers);
  font-size: 1.15rem;
  color: var(--blue-primary);
  font-weight: 700;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.feature-box h3 i {
  color: var(--gold-primary);
}

.feature-box p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.5;
}

.action-box {
  background: linear-gradient(135deg, rgba(90, 45, 130, 0.05) 0%, rgba(212, 175, 55, 0.05) 100%);
  border: 1.5px dashed var(--blue-primary);
  border-radius: var(--radius-md);
  padding: 30px;
  text-align: center;
  margin-top: 35px;
}

.action-box h3 {
  font-family: var(--font-headers);
  font-size: 1.3rem;
  color: var(--blue-primary);
  font-weight: 700;
  margin-bottom: 12px;
}

.action-box p {
  color: var(--text-secondary);
  font-size: 0.95rem;
  margin-bottom: 20px;
}

.btn-cta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 30px;
  background-color: var(--blue-primary);
  color: #fff;
  font-family: var(--font-headers);
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-radius: var(--radius-md);
  box-shadow: 0 4px 15px rgba(90, 45, 130, 0.25);
  transition: var(--transition-smooth);
}

.btn-cta:hover {
  background-color: var(--gold-primary);
  color: var(--blue-dark);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(212, 175, 55, 0.35);
}

@media (max-width: 992px) {
  .sys-layout {
    flex-direction: column;
  }

  .sys-sidebar {
    display: none !important;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }
}
